// Avisos derivados de documentos confirmados, sin escrituras adicionales ni duplicados.
// La campana es una vista de eventos; no se presenta como bandeja de lectura persistente.
function operationalAlerts(){
 const rows=[];
 for(const p of state.plans){
  if(p.status==='CANCELADO')continue;
  const base={planId:p.id,activity:p.activityName||'Actividad',analyst:p.analystName||'Analista'};
  if(p.createdAt?.seconds && p.status!=='CANCELADO')rows.push({...base,id:p.id+':assigned',kind:'ASIGNACION',date:p.createdAt,description:'Actividad asignada por planificación'});
  if(p.startedAt?.seconds)rows.push({...base,id:p.id+':open',kind:'APERTURA',date:p.startedAt,description:'Inicio de actividad confirmado'});
  if(p.finishedAt?.seconds)rows.push({...base,id:p.id+':close',kind:'CIERRE',date:p.finishedAt,description:'Finalización confirmada'});
 }
 return rows.sort((a,b)=>(b.date?.seconds||0)-(a.date?.seconds||0)).slice(0,30);
}
// Bounded conversation watchers: only recent 24 plans, one last-message document per plan.
let communicationsReturnPage='Inicio';
const readState={marks:{},latest:{},stops:new Map(),stopMarks:null,uid:null};
function unreadConversationCount(){return Object.entries(readState.latest).filter(([id,m])=>m&&m.authorId!==state.user?.uid&&readState.marks[id]?.messageId!==m.id).length}
function isArchivedPlan(id){const m=readState.marks[id]||{};const last=readState.latest[id];return m.archived===true&&(!last||last.authorId===state.user?.uid||m.messageId===last.id)}
function assignmentPending(p){if(!p?.createdAt?.seconds||p.status==='CANCELADO')return false;return state.profile?.role==='ANALISTA'&&readState.marks[p.id]?.assignmentSeen!==p.createdAt.seconds}
function unreadForPlan(id){const m=readState.latest[id];return !!(m&&m.authorId!==state.user?.uid&&readState.marks[id]?.messageId!==m.id)}
function clearReadWatches(){readState.stopMarks?.();readState.stopMarks=null;for(const stop of readState.stops.values())stop();readState.stops.clear();readState.marks={};readState.latest={};readState.uid=null}
function refreshReadWatches(){if(!state.user||!state.profile)return;const eligible=state.plans.filter(p=>p.status!=='CANCELADO').sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))).slice(0,24);const ids=new Set(eligible.map(p=>p.id));for(const [id,stop] of readState.stops)if(!ids.has(id)){stop();readState.stops.delete(id);delete readState.latest[id]}
 for(const id of ids){if(readState.stops.has(id))continue;readState.stops.set(id,watchCommunicationLastMessage(id,m=>{readState.latest[id]=m;if(['Centro de Comunicaciones','Inicio'].includes(state.page))main();else updateBellBadge()},e=>console.warn('Lectura de chat:',e.message)))}
}
function updateBellBadge(){const n=unreadConversationCount()+state.plans.filter(assignmentPending).length;document.querySelectorAll('.count-dot,.nav-badge').forEach(el=>{el.textContent=n?String(n):'';el.hidden=!n})}
async function acknowledgeCommunication(planId){const latest=readState.latest[planId]||communicationState.messages[0];if(!latest?.id||latest.authorId===state.user?.uid)return;try{await markCommunicationRead(planId,latest.id)}catch(e){console.warn('Lectura no confirmada:',e.message)}}
function operationalAlertCount(){const since=Date.now()-24*3600*1000;return operationalAlerts().filter(a=>(a.date.seconds*1000)>=since).length;}

