function showLogin(){app.innerHTML=`<div class="auth-page"><div class="auth-decoration"><div class="brand auth-brand"><span class="brand-mark">P</span><span>LAB-PSI <small>PLANIFICACIÓN NEXTGEN</small></span></div><div class="auth-hero"><span class="eyebrow light">PLATAFORMA OPERATIVA · V29.0.18</span><h1>Un laboratorio.<br><em>Todo conectado.</em></h1><p>Planificación, ejecución y control técnico sobre un núcleo de sincronización compartido.</p><div class="auth-chips"><span>${ico('DatabaseZap')} Datos centralizados</span><span>${ico('ShieldCheck')} Acceso protegido</span></div></div><div class="auth-bottom">© 2026 LAB-PSI · Entorno NextGen V29</div></div><div class="auth-form-side"><div class="auth-card"><div class="mini-icon">${ico('LockKeyhole',24)}</div><span class="eyebrow">BIENVENIDO DE NUEVO</span><h2>Accede a tu espacio</h2><p>Ingresa con las credenciales autorizadas de Firebase Authentication.</p><form id="loginForm"><label>Correo electrónico<input type="email" name="email" placeholder="usuario@psi.com.ec" autocomplete="username" required></label><label>Contraseña<input type="password" name="password" placeholder="Tu contraseña" autocomplete="current-password" required></label><button class="primary full" type="submit" ${state.loading?'disabled':''}>${state.loading?'Conectando…':'Iniciar sesión'} ${ico('ArrowUpRight')}</button></form>${state.error?`<div class="error-msg">${ico('AlertCircle')} ${esc(state.error)}</div>`:''}<div class="auth-foot">Acceso sujeto a perfil ACTIVO y permisos asignados.</div></div></div></div>`;refreshIcons();document.querySelector('#loginForm').onsubmit=async e=>{e.preventDefault();const email=e.target.elements.namedItem('email').value;const password=e.target.elements.namedItem('password').value;state.loading=true;state.error='';showLogin();try{await signInWithEmailAndPassword(auth,email,password)}catch(err){state.loading=false;state.error=err.code==='auth/invalid-credential'?'Credenciales incorrectas.':err.message;showLogin()}}}
