 return `<div class="work94-toolbar" role="navigation" aria-label="Accesos operativos"><div class="work94-context"><span class="work94-dot"></span><span>LAB-PSI / ${esc(state.page)}</span></div><div class="work94-actions">${links.map(([page,label])=>`<button type="button" class="work94-action" data-page="${esc(page)}">${esc(label)} <span aria-hidden="true">↗</span></button>`).join('')}<button type="button" class="work94-action work94-home" data-page="Inicio" title="Ir a Inicio">Inicio</button></div></div>`;
