function navigate94(page){if(!nav.some(([n])=>n===page))return;if(state.profile?.role!=='JEFE'&&!analystPages.includes(page))return;if(page==='Centro de Comunicaciones'&&state.page!=='Centro de Comunicaciones')communicationsReturnPage=state.page;state.page=page;state.menu=false;main();window.scrollTo({top:0,behavior:'instant'});}
