function connectionDiagnosis(){
 const n=syncState.network;
 if(n==='offline'||!navigator.onLine)return {level:'red',title:'Sin conexión',detail:'Sin conexión a Internet. Los datos pueden ser locales.'};
 if(syncState.pending>0)return {level:'amber',title:'Operaciones pendientes',detail:`${syncState.pending} operación(es) esperando confirmación. No cierre la sesión.`};
 if(n==='cache'||syncState.cacheOnly&&!syncState.serverConfirmed)return {level:'amber',title:'Datos en caché',detail:'Esperando confirmación del servidor para las lecturas recientes.'};
 if(syncState.serverConfirmed&&n==='online')return {level:'green',title:'Firebase confirmado',detail:'Lecturas recibidas del servidor; sin escrituras pendientes en esta sesión.'};
 return {level:'blue',title:'Verificando conexión',detail:'Comprobando el estado del servidor; todavía sin confirmación reciente.'};
}
function refreshJourneyConnection(){
 const d=connectionDiagnosis();
 const badge=document.querySelector('#journeyConnectionBadge');
 if(badge){badge.textContent='● '+d.title;badge.className='live-badge connection-'+d.level;badge.title=d.detail}
 const strip=document.querySelector('#journeyConnectionStrip');
 if(strip){strip.querySelector('.journey-light').className='journey-light '+d.level;strip.querySelector('.journey-connection-title').textContent=d.title;strip.querySelector('.journey-connection-detail').textContent=d.detail}
}
function main(){const preservedModal=document.querySelector('#modalRoot')?.firstElementChild;const boss=state.profile.role==='JEFE';if(!boss&&!analystPages.includes(state.page))state.page='Inicio';const available=nav.filter(([name])=>boss||analystPages.includes(name));const current=nav.find(([n])=>n===state.page);const status=syncState.network;const notif=unreadConversationCount()+state.plans.filter(assignmentPending).length;app.innerHTML=`<div class="shell"><aside class="sidebar ${state.menu?'open':''} ${localStorage.getItem('psiSidebarCompact')==='1'?'compact':''}"><div class="brand"><span class="brand-mark">P</span><span>LAB-PSI <small>PLANIFICACIÓN NEXTGEN</small></span></div><div class="side-caption">ESPACIO DE TRABAJO <button type="button" id="sidebarCollapse" class="sidebar-collapse" title="Contraer o expandir menú">${ico('PanelLeftClose',16)}</button></div><nav>${NAV_ORDER.map(group=>{const items=available.filter(([name])=>NAV_GROUPS[name]===group);return items.length?`<div class="nav-group ${JSON.parse(localStorage.getItem('psiNavClosed')||'[]').includes(group)?'is-closed':''}"><button type="button" class="nav-group-label" data-nav-group="${group}" aria-expanded="${!JSON.parse(localStorage.getItem('psiNavClosed')||'[]').includes(group)}">${navSvg(NAV_ICONS[group],14)}<span>${group}</span>${ico('ChevronDown',13)}</button><div class="nav-group-items">${items.map(([name,icon])=>`<button data-page="${esc(name)}" title="${esc(name)}" class="nav-item ${state.page===name?'active':''}">${navSvg(icon)}<span>${esc(name)}</span>${name==='Centro de Comunicaciones'&&notif?`<b class="nav-badge">${notif}</b>`:''}</button>`).join('')}</div></div>`:''}).join('')}</nav><div class="sidebar-footer"><div class="core-status"><span class="status-dot"></span><span>NÚCLEO V29 <strong>ACTIVO</strong></span></div><p>Firebase independiente · Entorno V29</p><span class="version">NEXTGEN 29.0.115</span></div></aside><div class="main-area"><header class="topbar"><div class="top-left"><button class="icon-btn mobile-toggle" id="menuBtn">${ico('Menu')}</button><div class="breadcrumbs">LAB-PSI ${ico('ChevronRight',14)} <strong>${esc(state.page)}</strong></div></div><div class="top-right"><span class="sync-pill ${status==='offline'?'offline':''}"><span class="status-dot"></span>${syncState.pending?'Guardando…':status==='offline'?'Sin conexión':status==='cache'?'Datos en caché':status==='connecting'?'Conectando…':syncState.serverConfirmed?'Sincronizado':'Verificando…'}</span><button class="icon-btn" data-page="Centro de Comunicaciones" title="Notificaciones">${ico('Bell')}${notif?`<span class="count-dot">${notif}</span>`:''}</button><div class="profile-chip"><div class="avatar">${esc((state.profile.name||state.user.email).slice(0,1).toUpperCase())}</div><div><strong>${esc(state.profile.name||state.user.email)}</strong><small>${boss?'JEFE':'ANALISTA'}</small></div></div><button id="logout" class="icon-btn" title="Cerrar sesión">${ico('LogOut')}</button></div></header><main class="content">${workToolbar(boss)}${pageContent(boss)}</main></div></div>`;if(preservedModal&&['Reactivos y Materiales','Mi Jornada'].includes(state.page)){document.querySelector('#modalRoot')?.appendChild(preservedModal)}else{stopHistory()}refreshIcons();document.querySelectorAll('[data-page]').forEach(x=>x.onclick=()=>{if(x.dataset.page==='Centro de Comunicaciones'&&state.page!=='Centro de Comunicaciones')communicationsReturnPage=state.page;navigate94(x.dataset.page)});document.querySelectorAll('[data-nav-group]').forEach(btn=>btn.addEventListener('click',()=>{const group=btn.dataset.navGroup;const closed=new Set(JSON.parse(localStorage.getItem('psiNavClosed')||'[]'));closed.has(group)?closed.delete(group):closed.add(group);localStorage.setItem('psiNavClosed',JSON.stringify([...closed]));const parent=btn.closest('.nav-group');parent.classList.toggle('is-closed',closed.has(group));btn.setAttribute('aria-expanded',String(!closed.has(group)))}));document.querySelector('#logout').onclick=()=>signOut(auth);document.querySelector('.sidebar .brand-mark')?.addEventListener('click',()=>{const side=document.querySelector('.sidebar');if(side.classList.contains('compact')){side.classList.remove('compact');localStorage.setItem('psiSidebarCompact','0')}});document.querySelector('.sidebar .brand')?.addEventListener('click',()=>{const side=document.querySelector('.sidebar');if(side.classList.contains('compact')){side.classList.remove('compact');localStorage.setItem('psiSidebarCompact','0')}});document.querySelector('#sidebarCollapse')?.addEventListener('click',()=>{const side=document.querySelector('.sidebar');const compact=side.classList.toggle('compact');localStorage.setItem('psiSidebarCompact',compact?'1':'0')});document.querySelector('#menuBtn')?.addEventListener('click',()=>{state.menu=!state.menu;main()});bindPage();setupWork94();document.title=`LAB-PSI · ${state.page} · V29.0.115`;if(state.page==='Inicio'){bindPriorityPanel();bindControl95();}if(state.page==='Analistas'&&!state.analysts.length)document.querySelector('#loadAnalysts')?.click();if(state.page==='Planificador Inteligente'&&!state.plannerLoaded&&!state.plannerLoading){state.plannerLoading=true;Promise.all([readAnalysts(),readCompetencies()]).then(([a,c])=>{state.analysts=a;state.competencies=c;state.plannerLoaded=true;state.plannerLoading=false;if(state.page==='Planificador Inteligente')main()}).catch(e=>{state.plannerLoading=false;state.planMessage='No se pudieron cargar los analistas: '+e.message;if(state.page==='Planificador Inteligente')main()})}}
function heading(eyebrow,title,subtitle,action=''){return `<div class="page-heading"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`}
function pageContent(boss){if(state.page==='Inicio')return home(boss);if(state.page==='Catálogo Maestro')return catalog();if(state.page==='Reactivos y Materiales')return reagentsPage();if(state.page==='Analistas')return analysts();if(state.page==='Planificador Inteligente')return plannerPage();if(state.page==='Mi Jornada')return journeyPage();if(state.page==='Cartas de Control')return renderControlPage();if(state.page==='Seguimiento Diario')return dailyTrackingPage();if(state.page==='Dashboard Gestión')return managementDashboard();if(state.page==='Trazabilidad')return tracePage();if(state.page==='Centro de Comunicaciones')return communications();if(state.page==='Alertas Técnicas')return technicalBoard();if(state.page==='Configuración')return settings();return pendingPage()}
function priorityPanel(boss,today){
 // Solo evidencia recibida en las consultas autorizadas; ninguna escritura ni aviso adicional.
 const clock=new Date();const minute=clock.getHours()*60+clock.getMinutes();
 const delayed=state.plans.filter(p=>p.status==='PROGRAMADO'&&p.date===today&&Number.isFinite(Number(p.endMin))&&Number(p.endMin)<minute);
 const ongoing=state.plans.filter(p=>p.status==='EN_PROCESO');
 const messages=state.plans.filter(p=>unreadForPlan(p.id)&&!isArchivedPlan(p.id));
 const assigned=boss?[]:state.plans.filter(assignmentPending);
 const rows=[...delayed.map(p=>({id:'late:'+p.id,plan:p,kind:'retraso',title:'Actividad programada fuera de horario',detail:'Hora prevista de fin: '+ptime(Number(p.endMin)),rank:1})),...messages.map(p=>({id:'msg:'+p.id,plan:p,kind:'mensaje',title:'Mensaje nuevo sin leer',detail:'Conversación pendiente de lectura',rank:2})),...assigned.map(p=>({id:'assign:'+p.id,plan:p,kind:'asignacion',title:'Nueva asignación pendiente de revisar',detail:'Revisa los detalles de tu jornada',rank:3})),...ongoing.map(p=>({id:'ongoing:'+p.id,plan:p,kind:'proceso',title:'Actividad en ejecución',detail:'Pendiente de cierre confirmado',rank:4}))];
 const seen=new Set();const unique=rows.filter(r=>{if(seen.has(r.id))return false;seen.add(r.id);return true}).sort((a,b)=>a.rank-b.rank||String(a.plan.date||'').localeCompare(String(b.plan.date||''))).slice(0,12);
 const critical=unique.filter(r=>r.kind==='retraso').length;
 const unread=unique.filter(r=>r.kind==='mensaje').length;
 const filters=[['todos','Todas'],['retraso','Atrasadas'],['mensaje','Mensajes'],['asignacion','Asignaciones'],['proceso','En proceso']];
 return `<section class="panel priority-panel" id="homePriority"><div class="panel-heading"><div><span class="eyebrow">TRIAJE OPERATIVO · DATOS CONFIRMADOS</span><h3>Alertas y acciones prioritarias</h3><p>Un asunto por actividad y categoría. No se generan notificaciones adicionales.</p></div><span class="priority-total">${unique.length} asuntos visibles</span></div><div class="priority-stats"><span class="priority-stat red"><b>${critical}</b> Fuera de horario</span><span class="priority-stat purple"><b>${unread}</b> Mensajes sin leer</span><span class="priority-stat amber"><b>${ongoing.length}</b> En ejecución</span></div><div class="priority-filters" role="group" aria-label="Filtrar prioridades">${filters.map(([k,label])=>`<button type="button" class="priority-filter ${k==='todos'?'selected':''}" data-priority-filter="${k}">${label}</button>`).join('')}</div><div class="priority-list">${unique.length?unique.map(r=>`<article class="priority-row ${r.kind}" data-priority-kind="${r.kind}"><span class="priority-mark">${r.kind==='retraso'?'!':r.kind==='mensaje'?'✉':r.kind==='asignacion'?'＋':'◷'}</span><div class="priority-info"><strong>${esc(r.title)}</strong><span>${esc(r.plan.activityName||'Actividad')} · ${esc(r.plan.date||'')} ${boss?'· '+esc(r.plan.analystName||'Analista'):''}</span><small>${esc(r.detail)}</small></div><button type="button" class="outline small-btn" data-page="${r.kind==='mensaje'?'Centro de Comunicaciones':boss?'Seguimiento Diario':'Mi Jornada'}">${r.kind==='mensaje'?'Ver conversación':'Ver actividad'}</button></article>`).join(''):`<div class="home-empty"><strong>Sin asuntos prioritarios en los registros consultados</strong><small>Los indicadores se actualizan con las consultas actuales de Firebase.</small></div>`}</div><p class="priority-foot">Alcance: ${boss?'actividades consultadas por JEFE':'solo actividades autorizadas del analista'}. Las incidencias técnicas se consultan en el expediente y en el Centro de Comunicaciones; no se clasifican automáticamente sin evidencia específica.</p></section>`;
}
function bindPriorityPanel(){const root=document.querySelector('#homePriority');if(!root)return;root.querySelectorAll('[data-priority-filter]').forEach(button=>button.addEventListener('click',()=>{const kind=button.dataset.priorityFilter;root.querySelectorAll('[data-priority-filter]').forEach(b=>b.classList.toggle('selected',b===button));root.querySelectorAll('[data-priority-kind]').forEach(row=>{row.hidden=kind!=='todos'&&row.dataset.priorityKind!==kind})}))}
// V29.0.95: panel ejecutivo derivado de los datos ya recibidos. No crea listeners ni documentos.
let control95Filter='TODOS';
function control95Panel(){
 if(state.profile?.role!=='JEFE')return '';
 const now=new Date(),today=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-');
 const current=now.getHours()*60+now.getMinutes();
 const plans=state.plans.filter(p=>p.status!=='CANCELADO');
 const pending=plans.filter(p=>p.status==='PROGRAMADO'&&p.date<=today);
 const delayed=pending.filter(p=>p.date<today||(p.date===today&&Number.isFinite(Number(p.endMin))&&Number(p.endMin)<current));
 const open=plans.filter(p=>p.status==='EN_PROCESO');
 const unread=plans.filter(p=>unreadForPlan(p.id)&&!isArchivedPlan(p.id));
 const critical=techBoard91.rows.filter(a=>a.severity==='CRITICA'&&a.status!=='RESUELTA');
 const unresolved=techBoard91.rows.filter(a=>a.status!=='RESUELTA');
 const rows=[...critical.map(a=>({kind:'CRITICA',title:a.title||a.message||a.description||'Incidencia técnica crítica',who:a.analystName||'Analista',date:a.date||'',planId:a.planId,where:'Alertas Técnicas'})),...delayed.map(p=>({kind:'ATRASADA',title:p.activityName,who:p.analystName,date:p.date,planId:p.id,where:'Seguimiento Diario'})),...unread.map(p=>({kind:'MENSAJE',title:p.activityName,who:p.analystName,date:p.date,planId:p.id,where:'Centro de Comunicaciones'})),...open.map(p=>({kind:'EN_PROCESO',title:p.activityName,who:p.analystName,date:p.date,planId:p.id,where:'Seguimiento Diario'}))];
 const filtered=(control95Filter==='TODOS'?rows:rows.filter(r=>r.kind===control95Filter)).slice(0,14);
 const cards=[['ATRASADA','Actividades atrasadas',delayed.length,'warning'],['CRITICA','Incidencias críticas',critical.length,'danger'],['MENSAJE','Mensajes sin leer',unread.length,'info'],['EN_PROCESO','Actividades en ejecución',open.length,'success']];
 return `<section class="panel control95" id="control95"><div class="control95-head"><div><span class="eyebrow">DIRECCIÓN TÉCNICA · CONTROL OPERATIVO</span><h3>Centro de Control del JEFE</h3><p>Prioridades consolidadas a partir de registros disponibles en Firebase, sin generar notificaciones duplicadas.</p></div><button type="button" class="outline" id="control95Reset">Ver todas las prioridades</button></div><div class="control95-kpis">${cards.map(([kind,label,n,tone])=>`<button type="button" class="control95-kpi ${tone} ${control95Filter===kind?'selected':''}" data-control95-filter="${kind}"><small>${esc(label)}</small><strong>${n}</strong><span>${kind==='CRITICA'&&!techBoard91.loaded?'Consulta técnica pendiente':n?'Consultar detalles':'Sin asuntos detectados'}</span></button>`).join('')}</div><div class="control95-summary"><strong>${rows.length} asuntos identificados</strong><span>${techBoard91.loaded?`${unresolved.length} incidencias técnicas abiertas/en seguimiento entre ${techBoard91.rows.length} consultadas`:'Incidencias técnicas: pulse «Consultar incidencias» para actualizar la muestra de hasta 40 actividades.'}</span><button type="button" class="outline" id="control95Technical">${techBoard91.loading?'Consultando…':'Consultar incidencias'}</button></div><div class="control95-list">${filtered.length?filtered.map(r=>`<div class="control95-row"><span class="control95-tag ${r.kind.toLowerCase()}">${r.kind==='CRITICA'?'CRÍTICA':r.kind==='EN_PROCESO'?'EN PROCESO':r.kind}</span><div><strong>${esc(r.title)}</strong><small>${esc(r.who)} · ${esc(r.date||'Fecha no disponible')}</small></div><button type="button" class="outline" data-control95-open="${esc(r.where)}" data-control95-plan="${esc(r.planId||'')}">Ver expediente →</button></div>`).join(''):'<p class="control95-empty">No hay asuntos de esta categoría dentro de los registros consultados.</p>'}</div><p class="control95-note">Alcance: asignaciones actualmente consultadas y últimas conversaciones observadas (máximo 24). Las incidencias técnicas se consultan a petición (máximo 40 actividades); estos indicadores no representan un recuento histórico completo.</p></section>`;
}
function bindControl95(){const root=document.querySelector('#control95');if(!root)return;
 root.querySelectorAll('[data-control95-filter]').forEach(b=>b.onclick=()=>{control95Filter=control95Filter===b.dataset.control95Filter?'TODOS':b.dataset.control95Filter;main()});
 root.querySelector('#control95Reset')?.addEventListener('click',()=>{control95Filter='TODOS';main()});
 root.querySelector('#control95Technical')?.addEventListener('click',()=>loadTechnicalBoard91());
 root.querySelectorAll('[data-control95-open]').forEach(b=>b.onclick=()=>{if(b.dataset.control95Open==='Centro de Comunicaciones'&&b.dataset.control95Plan)communicationState.selected=b.dataset.control95Plan;navigate94(b.dataset.control95Open)});
}
function home(boss){
 const now=new Date();const today=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-');
 const relevant=state.plans.filter(p=>p.status!=='CANCELADO'); // La suscripción watchMyPlans ya restringe el alcance del ANALISTA.
 const todays=relevant.filter(p=>p.date===today);
 const done=todays.filter(p=>p.status==='REALIZADO').length;
 const running=todays.filter(p=>p.status==='EN_PROCESO').length;
 const queued=todays.filter(p=>p.status==='PROGRAMADO').length;
 const pending=unreadConversationCount()+state.plans.filter(assignmentPending).length;
 const delayed=todays.filter(p=>p.status==='PROGRAMADO'&&Number.isFinite(Number(p.endMin))&&Number(p.endMin)<new Date().getHours()*60+new Date().getMinutes());
 const completion=todays.length?Math.round(done/todays.length*100):0;
 const fmtTime=p=>Number.isFinite(Number(p.startMin))?ptime(Number(p.startMin)):'—';
 const statusLabel=p=>p.status==='REALIZADO'?'Realizada':p.status==='EN_PROCESO'?'En proceso':'Programada';
 const statusClass=p=>p.status==='REALIZADO'?'complete':p.status==='EN_PROCESO'?'progress':'planned';
 const urgent=[...todays].filter(p=>p.status==='EN_PROCESO'||delayed.includes(p)).sort((a,b)=>Number(a.startMin||0)-Number(b.startMin||0)).slice(0,4);
 const agenda=[...todays].sort((a,b)=>Number(a.startMin||0)-Number(b.startMin||0)).slice(0,8);
 return `${heading('CENTRO DE OPERACIONES','Buen día, '+esc((state.profile.name||'usuario').split(' ')[0])+'.',boss?'Panorama ejecutivo de la operación: cumplimiento, incidencias prioritarias y sincronización de registros.':'Acceso directo a las actividades asignadas, registros técnicos y comunicaciones de tu jornada.',`<span class="date-tag">${new Intl.DateTimeFormat('es-EC',{dateStyle:'full'}).format(new Date())}</span>`)}
 <section class="home-command"><div><span class="home-command-label">${ico('Sparkles',17)} ${boss?'PANEL DE SUPERVISIÓN':'ESPACIO PERSONAL DEL ANALISTA'}</span><h2>${boss?'Laboratorio bajo control.':'Tu jornada, organizada.'}</h2><p>${boss?'Prioriza actividades abiertas, retrasos y comunicaciones sin salir del núcleo operativo.':'Consulta tus asignaciones y confirma cada operación desde Mi Jornada.'}</p><div class="home-command-actions"><button class="home-primary" data-page="${boss?'Seguimiento Diario':'Mi Jornada'}">${ico('ClipboardList',17)} ${boss?'Ver seguimiento diario':'Abrir Mi Jornada'}</button><button class="home-secondary" data-page="Centro de Comunicaciones">${ico('MessageCircle',17)} Mensajes ${pending?`· ${pending} por revisar`:''}</button></div></div><div class="home-command-orbit">${ico('Activity',72)}<span>LAB-PSI · NEXTGEN</span></div></section>
 <div class="home-status-line"><span class="home-status-chip ${syncState.network==='offline'?'danger':''}">${ico('Wifi',15)} ${syncState.network==='offline'?'Sin conexión':syncState.network==='cache'?'Datos en caché':syncState.serverConfirmed?'Firebase sincronizado':'Verificando Firebase'}</span><span>${syncState.pending?syncState.pending+' escrituras pendientes':'Sin escrituras pendientes en esta sesión'}</span><span>${boss?'Vista general autorizada':'Vista restringida a tu usuario'}</span></div>
 <div class="home-kpi-grid">
 ${[['Actividades de hoy',todays.length,'Asignaciones visibles','CalendarDays','blue'],['Realizadas',done,completion+' % de las actividades de hoy','CheckCircle2','green'],['En proceso',running,'Requieren seguimiento','Timer','amber'],['Por iniciar',queued,'Actividades programadas','ClipboardList','slate'],['Conversaciones y avisos',pending,'Pendientes de lectura','Bell','purple'],['Programadas vencidas',delayed.length,'Según hora de fin prevista','AlertTriangle','red']].map(([title,val,detail,icon,tone])=>`<article class="home-kpi ${tone}"><div class="home-kpi-top"><span>${title}</span><span class="home-kpi-icon">${ico(icon,19)}</span></div><strong>${val}</strong><small>${detail}</small></article>`).join('')}</div>
 <div class="home-work-grid"><section class="panel home-work-panel"><div class="panel-heading"><div><span class="eyebrow">${boss?'SEGUIMIENTO OPERATIVO':'AGENDA PERSONAL'}</span><h3>${boss?'Actividades que requieren atención':'Mis actividades de hoy'}</h3><p>${boss?'En ejecución o con horario previsto vencido.':'Consulta tu planificación y estado actual.'}</p></div><button class="outline small-btn" data-page="${boss?'Seguimiento Diario':'Mi Jornada'}">Ver detalle ${ico('ArrowUpRight',15)}</button></div>
 ${(boss?urgent:agenda).length?`<div class="home-agenda">${(boss?urgent:agenda).map(p=>`<div class="home-agenda-row"><span class="home-agenda-time">${fmtTime(p)}</span><div><strong>${esc(p.activityName||'Actividad')}</strong><small>${boss?esc(p.analystName||'Analista')+' · ':''}${esc(p.area||'Laboratorio')}</small></div><span class="home-agenda-status ${statusClass(p)}">${delayed.includes(p)?'Vencida':statusLabel(p)}</span></div>`).join('')}</div>`:`<div class="home-empty">${ico('CheckCircle2',28)}<strong>${boss?'Sin actividades prioritarias en los registros consultados':'Sin actividades asignadas para hoy'}</strong><small>${boss?'Puedes consultar el seguimiento completo.':'Revisa Mi Jornada para consultar otras fechas.'}</small></div>`}</section>
 <section class="panel home-work-panel"><div class="panel-heading"><div><span class="eyebrow">COMUNICACIONES</span><h3>Centro de atención</h3><p>Mensajes, asignaciones y eventos operativos.</p></div></div><div class="home-comms-summary"><span class="home-comms-icon">${ico('MessageCircle',29)}</span><strong>${pending}</strong><span>aviso(s) por revisar</span></div><button class="home-comms-button" data-page="Centro de Comunicaciones">Abrir conversaciones ${ico('ArrowUpRight',16)}</button><div class="home-comms-foot">${boss?'Supervisa los expedientes y las respuestas del equipo.':'Solo verás las conversaciones de tus actividades.'}</div></section></div>
 ${boss?control95Panel():''}
 ${priorityPanel(boss,today)}
 <section class="panel home-bottom"><div class="panel-heading"><div><span class="eyebrow">ACCESOS DIRECTOS</span><h3>Herramientas de trabajo</h3></div></div><div class="home-shortcuts">${(boss?[['Planificador Inteligente','CalendarRange','Organizar la jornada'],['Dashboard Gestión','TrendingUp','Analizar resultados'],['Trazabilidad','ShieldCheck','Consultar expedientes'],['Reactivos y Materiales','FlaskConical','Controlar existencias']]:[['Mi Jornada','ClipboardList','Ejecutar actividades'],['Cartas de Control','Activity','Registrar controles'],['Seguimiento Diario','ChartNoAxesCombined','Revisar mi avance'],['Centro de Comunicaciones','Bell','Consultar mensajes']]).map(([name,icon,detail])=>`<button class="home-shortcut" data-page="${esc(name)}"><span>${ico(icon,21)}</span><strong>${esc(name)}</strong><small>${esc(detail)}</small>${ico('ArrowUpRight',15)}</button>`).join('')}</div></section>
 <p class="home-disclaimer">Indicadores calculados a partir de las actividades actualmente recibidas de Firebase. No incluyen registros fuera del alcance de la consulta activa. Los avisos se contabilizan sin crear documentos adicionales.</p>`;
}
