function linkedCards(activityId){return activityId?state.controlCards.filter(card=>card.status!=='INACTIVO'&&Array.isArray(card.activityIds)&&card.activityIds.includes(activityId)):[]}
function renderControlLinks(activityId){if(!activityId)return '<p class="control-readonly-empty">Guarde primero la actividad. Sus cartas vinculadas aparecerán aquí cuando se creen en Cartas de Control.</p>';if(state.controlCardsError)return `<p class="control-readonly-empty">No se pudo consultar las cartas: ${esc(state.controlCardsError)}. Revise los permisos de lectura.</p>`;const cards=linkedCards(activityId);return cards.length?`<div class="control-readonly-list">${cards.map(c=>`<div class="control-readonly-item"><strong>${esc(c.name||c.title||c.code||c.id)}</strong><small>${esc(c.code||c.id)} · ${esc(c.frequency||'Frecuencia por configurar')}</small></div>`).join('')}</div>`:'<p class="control-readonly-empty">Sin cartas vinculadas. La selección se realizará al crear cada carta en su propio módulo.</p>'}
function catalog(){const areas=CATALOG_AREAS;const areaIcons={'Ensayos Analíticos':'🧪','Recepción de Muestras':'📥','Microbiología':'🦠','AASS':'⚗️','Actividad de Laboratorio':'🔬','Soporte de Calidad':'✓','Operaciones':'⚙️'};const filtered=state.catalog.filter(x=>(state.catalogArea==='TODAS'||x.area===state.catalogArea)&&[x.name,x.area,x.method,x.code].join(' ').toLowerCase().includes(state.catalogFilter.toLowerCase()));return `${heading('CONFIGURACIÓN OPERATIVA','Catálogo Maestro','Biblioteca institucional de métodos y actividades: tiempos de referencia, parámetros, insumos asociados y control de versiones.',`<button class="primary" id="addCatalog">${ico('Plus')} Nueva actividad</button>`)}<div class="catalog-category-grid">${areas.map(a=>`<button class="catalog-category-card ${state.catalogArea===a?'selected':''}" data-catalog-area="${esc(a)}"><div class="catalog-card-top"><span class="catalog-card-symbol">${areaIcons[a]||'▦'}</span><strong>${state.catalog.filter(x=>x.area===a).length}</strong></div><span>${esc(a)}</span><small>${state.catalog.filter(x=>x.area===a&&x.active!==false).length} activas · ${state.catalog.filter(x=>x.area===a&&x.requiresCurve).length} con curva</small></button>`).join('')}<button class="catalog-category-card ${state.catalogArea==='TODAS'?'selected':''}" data-catalog-area="TODAS"><div class="catalog-card-top"><span class="catalog-card-symbol">▦</span><strong>${state.catalog.length}</strong></div><span>Todas las categorías</span></button></div><section class="panel catalog-panel"><div class="panel-heading"><div><span class="eyebrow">FICHAS TÉCNICAS · ${esc(state.catalogArea)}</span><h3>${filtered.length} actividades</h3><p class="catalog-intro">Seleccione una ficha para consultar su configuración, parámetros, reactivos y versión técnica.</p></div><label class="catalog-search">${ico('Search',18)}<input id="catalogSearch" value="${esc(state.catalogFilter)}" placeholder="Buscar actividad, código o método"></label></div><div class="table-wrap"><table><thead><tr><th>ACTIVIDAD / MÉTODO</th><th>ÁREA</th><th>TIEMPO</th><th>CONFIGURACIÓN</th><th>VERSIÓN</th><th>ACCIÓN</th></tr></thead><tbody>${filtered.map(x=>`<tr><td><strong>${esc(x.name)}</strong><small class="table-sub">${esc(x.code||'Sin código')} · ${esc(x.method||'Sin método')}</small></td><td>${esc(x.area)}</td><td>${formatDuration(x.durationMin)}</td><td>${(x.sampleParameters||[]).length} parámetros · ${(x.reactives||[]).length} reactivos ${x.requiresCurve?'· curva':''}</td><td><span class="catalog-version">v${Number(x.technicalVersion||1)}</span></td><td><button class="outline small-btn" data-view-catalog="${esc(x.id)}">Ver ficha</button> <button class="outline small-btn" data-edit-catalog="${esc(x.id)}">Editar</button></td></tr>`).join('')||'<tr><td colspan="6">Sin actividades en esta categoría.</td></tr>'}</tbody></table></div></section><div id="modalRoot"></div>`}
function stockFmt(n){return Number(n||0).toLocaleString('es-EC',{maximumFractionDigits:4})}
function reagentsPage(){
 const all=state.reagents;
 const available=all.filter(r=>Number(r.stock)>0&&r.status==='ACTIVO');
 const unique=new Set(all.map(r=>r.code||r.id)).size;
 const low=available.filter(r=>Number(r.minStock)>0&&Number(r.stock)<=Number(r.minStock));
 const exhausted=all.filter(r=>Number(r.stock)<=0||r.status!=='ACTIVO');
 const rows=available.filter(r=>[r.name,r.code,r.lot,r.brand].join(' ').toLowerCase().includes(state.reagentFilter.toLowerCase())
  &&(state.reagentType==='TODOS'||(r.productType||'REACTIVO')===state.reagentType)
  &&(state.reagentControl==='TODOS'||r.control===state.reagentControl)
  &&(state.reagentStock==='TODOS'||(state.reagentStock==='BAJO'?Number(r.minStock)>0&&Number(r.stock)<=Number(r.minStock):Number(r.minStock)===0||Number(r.stock)>Number(r.minStock))));
 const option=(v,label,current)=>`<option value="${v}" ${current===v?'selected':''}>${label}</option>`;
 return `${heading('INVENTARIO · LIMS ENTERPRISE','Reactivos y Materiales','Control metrológico del inventario: identificación de lotes y frascos, existencias disponibles y movimientos confirmados.',`<button class="primary" id="newReagent">${ico('Plus')} Nuevo producto / lote</button>`)}
 <div class="inventory-kpis" aria-label="Resumen de inventario">
  <div class="inventory-kpi"><span>Lotes disponibles</span><strong>${available.length}</strong><small>Con existencias y activos</small></div>
  <div class="inventory-kpi"><span>Productos únicos</span><strong>${unique}</strong><small>Códigos registrados</small></div>
  <div class="inventory-kpi ${low.length?'kpi-warning':''}"><span>Stock bajo</span><strong>${low.length}</strong><small>${low.length?'Requieren atención':'Sin alertas actuales'}</small></div>
  <div class="inventory-kpi"><span>Histórico / inactivos</span><strong>${exhausted.length}</strong><small>Registros conservados</small></div>
 </div>
 <section class="panel catalog-panel inventory-panel"><div class="panel-heading inventory-heading"><div><span class="eyebrow">CONTROL CENTRAL · POR LOTE</span><h3>Inventario disponible <span class="inventory-count">${rows.length} de ${available.length}</span></h3></div><div class="inventory-tools"><label class="catalog-search">${ico('Search',18)}<input id="reagentSearch" placeholder="Buscar nombre, código, lote o marca" value="${esc(state.reagentFilter)}" aria-label="Buscar inventario"></label><select id="reagentType" aria-label="Filtrar tipo de producto">${option('TODOS','Todos los productos',state.reagentType)}${option('REACTIVO','Reactivos',state.reagentType)}${option('ESTANDAR','Estándares',state.reagentType)}${option('MRC','Materiales de referencia',state.reagentType)}${option('INSUMO','Insumos',state.reagentType)}</select><select id="reagentControl" aria-label="Filtrar control">${option('TODOS','Todos los controles',state.reagentControl)}${option('COUNT','Contable',state.reagentControl)}${option('SOLID','Sólido pesable',state.reagentControl)}${option('LIQUID','Líquido pesable',state.reagentControl)}</select><select id="reagentStock" aria-label="Filtrar stock">${option('TODOS','Todas las existencias',state.reagentStock)}${option('BAJO','Stock bajo',state.reagentStock)}${option('NORMAL','Stock normal',state.reagentStock)}</select></div></div>
 <div class="table-wrap"><table class="inventory-table"><thead><tr><th>PRODUCTO / CÓDIGO</th><th>LOTE / FRASCO</th><th>EXISTENCIA ACTUAL</th><th>ESTADO</th><th>CONTROL</th><th>ASIGNACIONES</th><th>ACCIONES</th></tr></thead><tbody>${rows.map(r=>{const isLow=Number(r.minStock)>0&&Number(r.stock)<=Number(r.minStock);const count=(r.activityIds||[]).length;return `<tr><td><strong>${esc(r.name)}</strong><small class="table-sub">${esc(r.code)} · ${esc(r.brand||'Sin marca')}</small></td><td><span class="lot-chip">${esc(r.lot)}</span><small class="table-sub">Frasco ${esc(r.bottleId||r.id.slice(0,8).toUpperCase())}</small></td><td><strong class="stock-value">${stockFmt(r.stock)} <small>${esc(r.unit)}</small></strong>${Number(r.minStock)>0?`<small class="table-sub">Mínimo: ${stockFmt(r.minStock)} ${esc(r.unit)}</small>`:''}</td><td><span class="stock-badge ${isLow?'badge-low':'badge-ok'}">${isLow?'Stock bajo':'Disponible'}</span></td><td><span class="control-pill">${r.control==='COUNT'?'Contable':r.control==='SOLID'?'Sólido pesable':'Líquido pesable'}</span></td><td><span class="assignment-status ${count?'has-assignments':''}">${count?`${count} vinculada${count===1?'':'s'}`:'Sin asignación'}</span></td><td><div class="inventory-row-actions"><button type="button" class="outline small-btn" data-history-reagent="${esc(r.id)}" title="Consultar movimientos">Movimientos</button><details class="inventory-action-menu"><summary aria-label="Acciones para ${esc(r.name)}">Acciones ▾</summary><div class="inventory-action-list"><button type="button" data-edit-reagent="${esc(r.id)}">Editar / asignar</button><button type="button" data-consume-reagent="${esc(r.id)}">Registrar consumo</button><button type="button" data-replenish="${esc(r.id)}">+ Registrar entrada</button><button type="button" class="danger-action" data-retire-reagent="${esc(r.id)}">Retirar lote</button></div></details></div></td></tr>`}).join('')||'<tr><td colspan="7" class="empty-table">No hay lotes disponibles con los filtros seleccionados.</td></tr>'}</tbody></table></div>
 <details class="archive-box"><summary>Consultar lotes agotados e inactivos (${exhausted.length})</summary><div class="archive-items">${exhausted.map(r=>`<div><strong>${esc(r.name)}</strong> · ${esc(r.code)} · lote ${esc(r.lot)} · ${stockFmt(r.stock)} ${esc(r.unit)} <button class="outline small-btn" data-replenish="${esc(r.id)}">+ Reponer</button> <button class="outline small-btn" data-history-reagent="${esc(r.id)}">Movimientos</button> <button class="outline small-btn" data-edit-reagent="${esc(r.id)}">Editar / activar</button></div>`).join('')||'Sin lotes agotados.'}</div></details></section><div id="modalRoot"></div>`;
}
function openReagentForm(x={}){const choices=state.catalog.map(a=>`<label class="assignment-choice"><input type="checkbox" value="${esc(a.id)}" ${(x.activityIds||[]).includes(a.id)?'checked':''}><span><strong>${esc(a.name)}</strong><small>${esc(a.area||'')} · ${esc(a.code||'')}</small></span></label>`).join('');document.querySelector('#modalRoot').innerHTML=`<div class="modal-overlay"><form class="catalog-modal reagent-pro" id="reagentForm"><div class="modal-head"><div><span class="eyebrow">PRODUCTO / LOTE · ASIGNACIÓN INTELIGENTE</span><h2>${x.id?'Editar producto y asignaciones':'Nuevo producto / lote'}</h2><p class="muted">Identifique el producto, seleccione el tipo de medición y vincule las actividades del Catálogo Maestro.</p></div><button type="button" class="icon-btn" id="closeReagent">${ico('X')}</button></div><div class="catalog-form-body">${!x.id?`<div class="form-section"><h3>Alta inteligente · frascos individuales</h3><p class="form-help">Cada registro nuevo corresponde a un frasco independiente, aunque comparta producto, marca y lote. El código maestro se conserva por producto; cada frasco tiene su propia identificación y saldo.</p><label>Usar un producto existente<select id="existingBottleProduct"><option value="">Nuevo producto (escribir manualmente)</option>${state.reagents.map(r=>`<option value="${esc(r.id)}">${esc(r.name)} · ${esc(r.brand||'Sin marca')} · lote ${esc(r.lot)} · ${esc(r.code)}</option>`).join('')}</select></label><p id="bottleMatchHint" class="form-help">Seleccione un producto para copiar su configuración y registrar otro frasco o lote.</p></div>`:''}<div class="form-section"><h3>01 · Identificación del producto y lote</h3><div class="form-grid"><label>Producto *<input name="name" required maxlength="120" value="${esc(x.name||'')}"></label><label>Código automático<input name="code" readonly value="${esc(x.code||'Se asignará al guardar')}"></label><label>Lote *<input name="lot" required maxlength="80" value="${esc(x.lot||'')}"></label><label>Marca<input name="brand" maxlength="100" value="${esc(x.brand||'')}"></label><label>Presentación<input name="presentation" maxlength="120" placeholder="Ej. 500 g, 2.5 L, caja de 100" value="${esc(x.presentation||'')}"></label><label>Tipo de producto<select name="productType"><option value="REACTIVO" ${x.productType==='REACTIVO'?'selected':''}>Reactivo</option><option value="ESTANDAR" ${x.productType==='ESTANDAR'?'selected':''}>Estándar</option><option value="MRC" ${x.productType==='MRC'?'selected':''}>Material de referencia</option><option value="INSUMO" ${x.productType==='INSUMO'?'selected':''}>Insumo</option></select></label><label>Tipo de control<select name="control" id="controlSelect">${[['COUNT','Contable (unidades)'],['SOLID','Sólido pesable (tara / peso)'],['LIQUID','Líquido pesable (tara / peso / densidad)']].map(([v,l])=>`<option value="${v}" ${x.control===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Unidad<select name="unit" id="unitSelect"></select></label><label id="stockField">Existencia inicial / saldo disponible ${x.id?'(solo lectura)':''}<input name="stock" type="number" step="any" min="0" value="${x.stock??0}" ${x.id?'disabled':''} required></label><label id="grossField">Peso bruto inicial: envase + contenido (g)<input name="grossGrams" type="number" step="any" min="0" value="" placeholder="Ej. 370"></label><label id="tareField">Tara del envase vacío (g)<input name="tareGrams" type="number" step="any" min="0" value="${esc(x.tareGrams??0)}" placeholder="Ej. 120"></label><label id="densityField">Densidad del líquido (g/mL)<input name="densityGramsPerMl" type="number" step="any" min="0.000001" value="${esc(x.densityGramsPerMl??'')}" placeholder="Ej. 1.18"></label><label>Stock mínimo<input name="minStock" type="number" step="any" min="0" value="${x.minStock??0}" required></label><label>Estado<select name="status"><option value="ACTIVO" ${x.status!=='INACTIVO'?'selected':''}>ACTIVO</option><option value="INACTIVO" ${x.status==='INACTIVO'?'selected':''}>INACTIVO</option></select></label></div><div id="controlDescription" class="control-help"></div><div id="initialCalculation" class="control-help" aria-live="polite"></div></div><div class="form-section"><h3>02 · Asignación a técnicas y parámetros</h3><p class="form-help">Seleccione las actividades donde debe aparecer este lote como reactivo disponible. Se vincula por identificador de actividad, sin crear copias del inventario.</p><label class="catalog-search">${ico('Search')}<input type="search" id="assignmentSearch" placeholder="Buscar técnica, parámetro o actividad"></label><div class="assignment-grid" id="assignmentGrid">${choices||'<p>Primero registre actividades en el Catálogo Maestro.</p>'}</div></div></div><div id="reagentError" class="form-error"></div><div class="modal-actions"><button type="button" class="outline" id="cancelReagent">Cancelar</button><button type="submit" class="primary" id="submitReagent">${x.id?'Guardar producto y asignaciones':'Guardar producto y asignaciones'}</button></div></form></div>`;refreshIcons();const root=document.querySelector('#modalRoot'),form=root.querySelector('#reagentForm'),g=n=>form.elements.namedItem(n);const close=()=>root.innerHTML='';root.querySelector('#closeReagent').onclick=close;root.querySelector('#cancelReagent').onclick=close;const existing=root.querySelector('#existingBottleProduct');if(existing)existing.onchange=()=>{const r=state.reagents.find(v=>v.id===existing.value);if(!r)return;for(const key of ['name','brand','presentation','productType','control','minStock','tareGrams','densityGramsPerMl']){const el=g(key);if(el)el.value=r[key]??'';}g('lot').value=r.lot||'';root.querySelectorAll('.assignment-choice input').forEach(el=>el.checked=(r.activityIds||[]).includes(el.value));updateControl();g('unit').value=r.unit;root.querySelector('#bottleMatchHint').textContent='Producto '+r.code+' seleccionado. Puede conservar el lote para un frasco adicional o escribir otro lote. El saldo del nuevo frasco se registra por separado.';};const updateControl=()=>{const c=g('control').value,options=c==='COUNT'?['unidad']:c==='SOLID'?['g','kg']:['mL','L'];g('unit').innerHTML=options.map(v=>`<option value="${v}" ${v===x.unit?'selected':''}>${v}</option>`).join('');root.querySelector('#tareField').style.display=c==='COUNT'?'none':'';root.querySelector('#grossField').style.display=c==='COUNT'||x.id?'none':'';root.querySelector('#densityField').style.display=c==='LIQUID'?'':'none';const stockInput=g('stock');stockInput.readOnly=!x.id&&c!=='COUNT';stockInput.required=c==='COUNT'&&!x.id;g('grossGrams').required=!x.id&&c!=='COUNT';g('tareGrams').required=c!=='COUNT';g('densityGramsPerMl').required=c==='LIQUID';if(!x.id&&c!=='COUNT')stockInput.value='0';calculateInitial();root.querySelector('#controlDescription').textContent=c==='COUNT'?'Consumo en unidades enteras.':c==='SOLID'?'El consumo se calcula por diferencia de peso bruto (antes y después), con registro de tara.':'El consumo se calcula por diferencia de peso dividida entre la densidad (g/mL), con registro de tara.'};const calculateInitial=()=>{const c=g('control').value,box=root.querySelector('#initialCalculation');if(x.id){box.textContent='El saldo existente solo cambia mediante movimientos de inventario.';return}if(c==='COUNT'){box.textContent='Ingrese la cantidad de unidades recibidas. No se requiere tara ni densidad.';return}const gross=Number(g('grossGrams').value),tare=Number(g('tareGrams').value),density=Number(g('densityGramsPerMl').value);if(!g('grossGrams').value||!g('tareGrams').value){box.textContent='Ingrese peso bruto inicial y tara para calcular la existencia neta.';g('stock').value='0';return}if(!Number.isFinite(gross)||!Number.isFinite(tare)||tare<0||gross<=tare){box.textContent='El peso bruto debe superar la tara y ambos deben ser válidos.';g('stock').value='0';return}if(c==='LIQUID'&&(!Number.isFinite(density)||density<=0)){box.textContent='Ingrese una densidad positiva en g/mL para calcular el volumen.';g('stock').value='0';return}let quantity=c==='SOLID'?gross-tare:(gross-tare)/density;if(g('unit').value==='kg'||g('unit').value==='L')quantity/=1000;quantity=Math.round(quantity*1e6)/1e6;g('stock').value=String(quantity);box.textContent='Contenido neto: '+(gross-tare).toFixed(3)+' g · Existencia inicial calculada: '+quantity+' '+g('unit').value;};g('control').onchange=updateControl;['grossGrams','tareGrams','densityGramsPerMl','unit'].forEach(n=>g(n).addEventListener('input',calculateInitial));updateControl();root.querySelector('#assignmentSearch').oninput=e=>{const q=e.target.value.toLowerCase();root.querySelectorAll('.assignment-choice').forEach(el=>el.hidden=!el.textContent.toLowerCase().includes(q))};form.onsubmit=async e=>{e.preventDefault();const btn=root.querySelector('#submitReagent');btn.disabled=true;btn.textContent='Confirmando en Firebase…';try{if(!x.id&&g('control').value!=='COUNT'&&Number(g('stock').value)<=0)throw Error('Registre peso bruto, tara y densidad cuando corresponda; la existencia calculada debe ser positiva.');const activityIds=[...root.querySelectorAll('.assignment-choice input:checked')].map(el=>el.value);await saveReagent({id:x.id,name:g('name').value,code:x.code||'',lot:g('lot').value,brand:g('brand').value,presentation:g('presentation').value,productType:g('productType').value,control:g('control').value,unit:g('unit').value,stock:x.id?x.stock:Number(g('stock').value),minStock:Number(g('minStock').value),status:g('status').value,activityIds,tareGrams:g('control').value==='COUNT'?0:Number(g('tareGrams').value),densityGramsPerMl:g('control').value==='LIQUID'?Number(g('densityGramsPerMl').value):0},state.user.uid);close()}catch(err){root.querySelector('#reagentError').textContent=err.message;btn.disabled=false;btn.textContent='Reintentar'}}}
function operationalAnalyst(a){return a.role==='ANALISTA' && a.status==='ACTIVO' && a.operational!==false && a.participatesInPlanning!==false}
function competenceAreas(uid){const c=state.competencies[uid]||{};if(Array.isArray(c.areas))return c.areas;return [...new Set((c.activityIds||[]).map(id=>state.catalog.find(x=>x.id===id)?.area).filter(Boolean))]}
function renderAnalysts(rows){const operational=rows.filter(operationalAnalyst),chiefs=rows.filter(a=>a.role==='JEFE'),other=rows.filter(a=>!operationalAnalyst(a)&&a.role!=='JEFE');const capacity=operational.reduce((sum,a)=>sum+(Number(a.dailyHours??a.workHours??a.jornadaHoras??8)||0),0);return `<div class="analyst-summary"><div><strong>${operational.length}</strong><span>Analistas operativos</span></div><div><strong>${chiefs.length}</strong><span>Jefes administrativos</span></div><div><strong>${capacity} h</strong><span>Capacidad nominal diaria</span></div><div><strong>${other.length}</strong><span>Otros / no disponibles</span></div></div><p class="form-help">Competencias por sección del Catálogo Maestro. Las actividades nuevas de una sección autorizada se incorporarán automáticamente. Solo ANALISTA ACTIVO suma capacidad; los JEFE no reciben ensayos.</p><div class="analyst-list">${rows.map(a=>{const operative=operationalAnalyst(a),isChief=a.role==='JEFE',areas=competenceAreas(a.id);return `<div class="analyst-row"><span class="avatar">${esc((a.name||a.email||'?')[0])}</span><div><strong>${esc(a.name||a.email||a.id)}</strong><small>${esc(a.email||'')} · ${esc(a.position||a.cargo||'')}</small>${operative&&areas.length?`<div class="competence-area-tags">${areas.map(x=>`<span class="table-tag">${esc(x)}</span>`).join('')}</div>`:''}</div><span class="table-tag">${esc(a.role||'SIN ROL')}</span><span class="table-tag">${esc(a.status||'SIN ESTADO')}</span><span class="table-tag ${operative?'analyst-operational':'analyst-admin'}">${operative?'Operativo':isChief?'Administrativo · excluido':'No planificable'}</span><span class="table-tag">${operative?esc(String(Number(a.dailyHours??a.workHours??a.jornadaHoras??8)||0))+' h':'—'}</span>${operative?`<button class="outline small-btn" data-competence="${esc(a.id)}">Secciones (${areas.length})</button>`:''}</div>`}).join('')||'<p class="muted">No hay perfiles registrados.</p>'}</div>`}
function bindCompetenceButtons(){document.querySelectorAll('[data-competence]').forEach(b=>b.onclick=()=>openCompetencies(b.dataset.competence))}
function openCompetencies(uid){const a=state.analysts.find(x=>x.id===uid);if(!a||!operationalAnalyst(a))return;const selected=competenceAreas(uid);const root=document.createElement('div');root.id='competenceDialog';root.innerHTML=`<div class="modal-overlay"><form class="catalog-modal" id="competenceForm"><div class="modal-head"><div><span class="eyebrow">COMPETENCIAS POR SECCIÓN · V29.0.29</span><h2>${esc(a.name||a.email)}</h2><p>Autorice secciones completas, tal como en el catálogo original de analistas. No es necesario marcar cada ensayo.</p></div><button type="button" class="icon-btn" id="closeCompetence">${ico('X')}</button></div><div class="catalog-form-body"><div class="assignment-grid">${CATALOG_AREAS.map(area=>{const count=state.catalog.filter(x=>x.area===area&&x.active!==false).length;return `<label class="assignment-choice"><input type="checkbox" name="area" value="${esc(area)}" ${selected.includes(area)?'checked':''}><span><strong>${esc(area)}</strong><small>${count} actividades actuales · incluye automáticamente las futuras fichas de esta sección</small></span></label>`}).join('')}</div><p class="form-help">Los cambios se aplicarán a futuras asignaciones. No se modifican planificaciones ni actividades finalizadas. Los JEFE continúan excluidos.</p></div><div class="form-error" id="competenceError"></div><div class="modal-actions"><button type="button" class="outline" id="cancelCompetence">Cancelar</button><button class="primary" type="submit" id="saveCompetence">Guardar secciones en Firebase</button></div></form></div>`;document.body.appendChild(root);refreshIcons();const close=()=>root.remove();root.querySelector('#closeCompetence').onclick=close;root.querySelector('#cancelCompetence').onclick=close;root.querySelector('form').onsubmit=async e=>{e.preventDefault();const btn=root.querySelector('#saveCompetence');btn.disabled=true;try{const areas=[...root.querySelectorAll('input[name=area]:checked')].map(x=>x.value);await saveCompetencies(uid,areas,state.user.uid);state.competencies[uid]={areas};document.querySelector('#analystList').innerHTML=renderAnalysts(state.analysts);bindCompetenceButtons();close()}catch(err){root.querySelector('#competenceError').textContent='No se pudo guardar: '+err.message;btn.disabled=false}}}
function analysts(){return `${heading('GESTIÓN DE PERSONAL','Analistas y roles','Directorio de personal autorizado, funciones operativas y disponibilidad para la programación de ensayos.')}<div class="notice">${ico('ShieldCheck')} <div><strong>Separación segura de funciones</strong><p>El rol JEFE administra el sistema, pero no recibe ensayos ni suma horas de laboratorio. Los permisos se determinan desde el perfil real de Firebase; esta vista no modifica usuarios.</p></div></div><div class="panel"><div class="panel-heading"><h3>Equipo y disponibilidad nominal</h3><button class="outline" id="loadAnalysts">${ico('RefreshCw')} Actualizar desde Firebase</button></div><div id="analystList">${state.analysts.length?renderAnalysts(state.analysts):'<p class="muted">Consultando perfiles…</p>'}</div></div>`}
const communicationState={selected:'',details:null,loading:false,error:'',filter:'TODOS',messages:[],status:null,stopMessages:null,stopStatus:null,stopTechnical:null,technicalAlerts:[],busy:false,feedback:'',draft:'',search:'',onlyUnread:false,modalOpen:false};
function stopCommunicationWatch(){communicationState.stopMessages?.();communicationState.stopStatus?.();communicationState.stopTechnical?.();communicationState.stopMessages=null;communicationState.stopStatus=null;communicationState.stopTechnical=null;communicationState.technicalAlerts=[];}
function communicationDate(v){try{return v?.toDate?.().toLocaleString('es-EC',{dateStyle:'short',timeStyle:'short'})||'Pendiente'}catch{return 'Pendiente'}}
function communicationChatModal(selected){
 if(!communicationState.modalOpen||!selected)return '';
 const mine=state.user?.uid;
 const boss=state.profile?.role==='JEFE';
 const status=communicationState.status?.status||'ATENCION';
 const alerts=communicationState.technicalAlerts||[];
 const technicalBox=`<section class="technical90"><div class="technical90-head"><div><b>🧪 Centro de alertas técnicas</b><small>${alerts.filter(a=>a.status!=='RESUELTA').length} abiertas o en seguimiento · ${alerts.length} consultadas</small></div></div><div class="technical90-list">${alerts.map(a=>`<article class="technical90-item ${a.severity==='CRITICA'?'critical':a.severity==='REVISION'?'review':'info'}"><div><b>${a.severity==='CRITICA'?'🔴 Crítica':a.severity==='REVISION'?'🟠 Pendiente de revisión':'🔵 Informativa'}</b> · ${a.status==='RESUELTA'?'✓ Resuelta':a.status==='EN_SEGUIMIENTO'?'En seguimiento':'Abierta'}<small>${esc(a.authorName||'Analista')} · ${communicationDate(a.createdAt)}</small></div><p>${esc(a.description||'')}</p>${boss?`<div class="technical90-controls"><select data-tech-severity="${esc(a.id)}"><option value="INFORMATIVA" ${a.severity==='INFORMATIVA'?'selected':''}>Informativa</option><option value="REVISION" ${a.severity==='REVISION'?'selected':''}>Pendiente de revisión</option><option value="CRITICA" ${a.severity==='CRITICA'?'selected':''}>Crítica</option></select><select data-tech-status="${esc(a.id)}"><option value="ABIERTA" ${a.status==='ABIERTA'?'selected':''}>Abierta</option><option value="EN_SEGUIMIENTO" ${a.status==='EN_SEGUIMIENTO'?'selected':''}>En seguimiento</option><option value="RESUELTA" ${a.status==='RESUELTA'?'selected':''}>Resuelta</option></select><input data-tech-note="${esc(a.id)}" maxlength="600" placeholder="Motivo obligatorio de la revisión"><button class="outline" data-tech-save="${esc(a.id)}">Guardar revisión</button></div>`:''}<details><summary>Historial de seguimiento (${(a.history||[]).length})</summary>${(a.history||[]).map(h=>`<p class="technical90-history">${esc(h.at||'')} · ${esc(h.action||'')} · ${esc(h.detail||'')} · ${esc(h.actorId||'')}</p>`).join('')}</details></article>`).join('')||'<p class="muted">No hay incidencias técnicas registradas en esta actividad.</p>'}</div><div class="technical90-new"><label for="technical90Description">Registrar nueva novedad técnica</label><textarea id="technical90Description" rows="2" maxlength="1200" placeholder="Describa el hallazgo, repetición o incidencia verificable…"></textarea><button class="outline" id="technical90Report">＋ Registrar novedad</button><small>El JEFE clasifica y cierra las incidencias. Las conversaciones se mantienen en el chat, sin modificar el ensayo ni inventario.</small></div></section>`;
 const bubbles=[...communicationState.messages].reverse().map(m=>`<article class="comm78-bubble ${m.authorId===mine?'mine':'theirs'}"><strong>${esc(m.authorId===mine?'Tú':m.authorName||'Usuario')}</strong><p>${esc(m.body||'')}</p><small>${communicationDate(m.createdAt)}${m.authorId===mine?' · ✓ Enviado':''}</small></article>`).join('');
 return `<div class="comm78-overlay" id="comm78Overlay"><section class="comm78-dialog" role="dialog" aria-modal="true" aria-labelledby="comm78Title"><header class="comm78-header"><div><span class="comm78-eyebrow">CHAT Y ALERTAS TÉCNICAS · V29.0.90</span><h2 id="comm78Title">${esc(selected.activityName||'Actividad')}</h2><p>${esc(selected.analystName||'Analista')} · ${esc(selected.date||'')} · ${esc(selected.status||'')}</p></div><button type="button" class="comm78-close" id="comm78Close" aria-label="Cerrar conversación">×</button></header><div class="comm78-toolbar"><span>💬 Conversación vinculada al expediente</span>${boss?`<label>Seguimiento <select id="comm78Attention"><option value="ATENCION" ${status==='ATENCION'?'selected':''}>🔴 Requiere atención</option><option value="SEGUIMIENTO" ${status==='SEGUIMIENTO'?'selected':''}>🟡 En seguimiento</option><option value="ATENDIDO" ${status==='ATENDIDO'?'selected':''}>🟢 Atendido</option></select></label>`:`<span>Estado: ${esc(status)}</span>`}</div>${technicalBox}<div class="comm78-thread" id="comm78Thread" aria-live="polite">${bubbles||'<p class="comm78-empty">No hay mensajes todavía. Escriba el primero para iniciar el seguimiento.</p>'}</div><div class="comm78-compose"><label for="comm78Reply">Mensaje o respuesta</label><textarea id="comm78Reply" maxlength="1500" rows="2" placeholder="Escribir comentario… (Ctrl + Enter para enviar)">${esc(communicationState.draft||'')}</textarea><div class="comm78-actions"><span id="comm78Feedback" role="status">${esc(communicationState.feedback||'Los mensajes se guardan en Firebase.')}</span><button type="button" class="primary" id="comm78Send" ${communicationState.busy?'disabled':''}>${communicationState.busy?'Enviando…':'➤ Enviar mensaje'}</button></div></div></section></div>`;
}
function communications(){
 const plans=[...state.plans].filter(p=>p.status!=='CANCELADO').sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))||Number(b.startMin||0)-Number(a.startMin||0));
 const filtered=plans.filter(p=>{const archived=isArchivedPlan(p.id),unread=unreadForPlan(p.id),assigned=assignmentPending(p);const f=communicationState.filter;return (f==='TODOS'?!archived:f==='ARCHIVADOS'?archived:f==='NUEVOS'?unread||assigned:f==='PENDIENTES'?!archived&&(unread||assigned||p.status==='EN_PROCESO'):f==='SEGUIMIENTO'?!archived&&!unread&&!assigned&&p.status==='EN_PROCESO':f===p.status)&&(!communicationState.search||`${p.activityName||''} ${p.analystName||''} ${p.date||''}`.toLocaleLowerCase().includes(communicationState.search.toLocaleLowerCase()))});
 const selected=plans.find(p=>p.id===communicationState.selected);
 const tech=communicationState.details?.tech,cons=communicationState.details?.consumptions||[];
 const isBoss=state.profile?.role==='JEFE';
 const items=[];
 if(selected?.startedAt)items.push({date:selected.startedAt,title:'▶ Apertura confirmada',body:`${selected.analystName||'Analista'} inició la actividad.`});
 if(tech?.updatedAt)items.push({date:tech.updatedAt,title:'🧪 Registro técnico',body:`${Number(tech.sampleCount||0)} muestras únicas. ${(tech.parameters||[]).map(x=>`${x.name||x.parameter||'Parámetro'}: ${x.count??x.quantity??0}`).join(' · ')||'Sin determinaciones'}`});
 for(const c of cons)items.push({date:c.createdAt,title:'📦 Consumo confirmado',body:`${c.reagentName||state.reagents.find(r=>r.id===c.reagentId)?.name||c.reagentId} · ${c.quantity} ${c.unit||''} · ${c.notes||'Sin comentario'}`});
 if(tech?.observations?.trim())items.push({date:tech.updatedAt,title:'💬 Novedad técnica registrada',body:tech.observations});
 if(selected?.finishedAt)items.push({date:selected.finishedAt,title:'✅ Cierre confirmado',body:`${selected.analystName||'Analista'} finalizó la actividad.`});
 items.sort((a,b)=>(a.date?.seconds||0)-(b.date?.seconds||0));
 return `<div class="comm80-backdrop" id="comm80Backdrop"><section class="comm80-window" role="dialog" aria-modal="true" aria-label="Centro de Comunicaciones"><div class="comm80-top"><strong>🔔 Centro de Comunicaciones · V29.0.82</strong><button class="outline" id="comm80Close" type="button">✕ Cerrar</button></div>${heading('COMUNICACIÓN Y SEGUIMIENTO','Centro de Comunicaciones','Comunicación técnica por expediente: asignaciones, novedades, respuestas y evidencias de ejecución verificables.')}<section class="comm-alert-panel"><div class="comm-alert-head"><div><h3>🔔 Eventos operativos recientes</h3><p>Asignaciones, aperturas y cierres de las últimas 24 horas; sin duplicar registros en Firebase.</p></div><strong>${operationalAlertCount()} recientes</strong></div><div class="comm-alert-list">${operationalAlerts().filter(a=>a.date.seconds*1000>=Date.now()-86400000).slice(0,12).map(a=>`<button class="comm-alert" data-comm-plan="${esc(a.planId)}"><b>${a.kind==='APERTURA'?'▶':a.kind==='ASIGNACION'?'📋':'✓'} ${esc(a.kind)}</b><span>${esc(a.activity)} · ${esc(a.analyst)}</span><small>${communicationDate(a.date)}</small></button>`).join('')||'<p class="muted">No hay aperturas ni cierres recientes en las actividades consultadas.</p>'}</div></section><div class="comm-summary"><span><b>${plans.filter(p=>p.status==='EN_PROCESO').length}</b> En proceso</span><span><b>${plans.filter(p=>p.status==='REALIZADO').length}</b> Realizadas</span><span><b>${plans.length}</b> Actividades consultadas</span></div><div class="comm-layout comm-chat-layout"><section class="panel comm-list"><div class="panel-heading"><h3>💬 Conversaciones ${unreadConversationCount()?`<span class="comm79-pill">${unreadConversationCount()} sin leer</span>`:''}</h3><select id="commFilter"><option value="TODOS">📥 Bandeja activa</option><option value="NUEVOS">🔵 Nuevos</option><option value="PENDIENTES">🔴 Pendientes</option><option value="SEGUIMIENTO">🟡 En seguimiento</option><option value="ARCHIVADOS">🗂 Archivados</option><option value="EN_PROCESO">En proceso</option><option value="REALIZADO">Realizadas</option><option value="PROGRAMADO">Programadas</option></select></div><input id="commSearch" class="comm-chat-search" type="search" placeholder="Buscar actividad o analista…" value="${esc(communicationState.search)}"><div class="comm-list-scroll">${filtered.length?filtered.map(p=>`<button class="comm-card ${p.id===communicationState.selected?'chosen':''}" data-comm-plan="${esc(p.id)}"><strong>${esc(p.activityName||'Actividad')}</strong>${unreadForPlan(p.id)?'<span class="comm79-new">● Mensaje nuevo</span>':assignmentPending(p)?'<span class="comm79-new">📋 Asignación nueva</span>':''}${isArchivedPlan(p.id)?'<span class="comm81-archived">🗂 Archivada</span>':''}<small>${esc(p.analystName||'Analista')} · ${esc(p.date||'')}</small><span class="comm-state">${p.status==='REALIZADO'?'✓ REALIZADA':p.status==='EN_PROCESO'?'● EN PROCESO':'○ PROGRAMADA'}</span></button>`).join(''):'<p class="muted">No hay actividades para este filtro.</p>'}</div></section><section class="panel comm-detail"><div class="panel-heading"><div><h3>${selected?esc(selected.activityName):'Seleccione una actividad'}</h3>${selected?`<p class="muted">${esc(selected.analystName||'')} · ${esc(selected.date||'')} · ${esc(selected.status||'')}</p>`:''}</div>${selected?`<div class="comm78-head-actions"><button class="primary" id="comm78Open">💬 Abrir chat</button><button class="outline" id="comm81Archive">${isArchivedPlan(selected.id)?'↩ Restaurar':'🗂 Archivar'}</button><button class="outline" id="commRefresh">↻ Actualizar evidencia</button></div>`:''}</div>${!selected?'<div class="empty-state"><h3>Expediente de seguimiento</h3><p>Seleccione una actividad para consultar su apertura, muestras, reactivos, novedades y cierre.</p></div>':communicationState.loading?'<p class="muted">Consultando evidencias confirmadas en Firebase…</p>':communicationState.error?`<p class="form-error">${esc(communicationState.error)}</p>`:communicationState.details?.planId!==selected.id?'<p class="muted">Cargando expediente…</p>':items.length?`<div class="comm-timeline comm-chat-events">${items.map(i=>`<article class="comm-event"><small>${communicationDate(i.date)}</small><h4>${esc(i.title)}</h4><p>${esc(i.body)}</p></article>`).join('')}</div>`:'<div class="empty-state"><h3>Sin eventos confirmados</h3><p>La actividad todavía no registra apertura, datos técnicos ni consumos.</p></div>'}${selected?`<div class="comm-conversation"><h3>💬 Conversación y seguimiento</h3><p class="muted">Mensajes confirmados en Firebase, asociados a esta actividad.</p>${isBoss?`<label class="comm-label">Estado de atención <select id="commAttention"><option value="ATENCION" ${(!communicationState.status?.status||communicationState.status?.status==='ATENCION')?'selected':''}>🔴 Requiere atención</option><option value="SEGUIMIENTO" ${communicationState.status?.status==='SEGUIMIENTO'?'selected':''}>🟡 En seguimiento</option><option value="ATENDIDO" ${communicationState.status?.status==='ATENDIDO'?'selected':''}>🟢 Atendido</option></select></label>`:`<p class="muted">Seguimiento: ${esc(communicationState.status?.status||'Pendiente de revisión')}</p>`}<div class="comm-messages comm-chat-messages" aria-live="polite">${communicationState.messages.length?[...communicationState.messages].reverse().map(m=>`<div class="comm-message comm-bubble ${m.authorId===state.user.uid?'mine':'theirs'}"><strong>${esc(m.authorId===state.user.uid?'Tú':m.authorName||'Usuario')}</strong><p>${esc(m.body||'')}</p><small>${communicationDate(m.createdAt)} ${m.authorId===state.user.uid?'✓ Enviado':''}</small></div>`).join(''):'<p class="muted">Todavía no hay respuestas en este expediente.</p>'}</div><label class="comm-label" for="commReply">Escribir comentario o respuesta</label><textarea id="commReply" rows="2" maxlength="1500" placeholder="Escribir mensaje… (Ctrl + Enter para enviar)">${esc(communicationState.draft||'')}</textarea><button class="primary" id="commSend" ${communicationState.busy?'disabled':''}>${communicationState.busy?'Enviando…':'➤ Enviar mensaje'}</button>${communicationState.feedback?`<p class="muted">${esc(communicationState.feedback)}</p>`:''}</div>`:''}<p class="comm-disclaimer">Apertura, muestras, consumos y cierre se consultan de sus registros reales. Los mensajes y estados de seguimiento se guardan por separado, sin modificar inventario ni cierres.</p></section></div>${communicationChatModal(selected)}`+`</section></div>`;
}
async function loadCommunication(planId){const ap=state.plans.find(p=>p.id===planId);if(ap&&assignmentPending(ap)){markAssignmentSeen(planId,ap.createdAt.seconds).catch(e=>console.warn('Asignación pendiente:',e.message))}stopCommunicationWatch();communicationState.selected=planId;communicationState.modalOpen=true;communicationState.draft='';communicationState.loading=true;communicationState.error='';communicationState.feedback='';communicationState.messages=[];communicationState.status=null;communicationState.details=null;main();
 communicationState.stopMessages=watchCommunicationMessages(planId,rows=>{if(communicationState.selected!==planId)return;communicationState.messages=rows;if(communicationState.modalOpen)acknowledgeCommunication(planId);if(state.page==='Centro de Comunicaciones')main()},e=>{communicationState.feedback='Mensajes: '+e.message;if(state.page==='Centro de Comunicaciones')main()});
 communicationState.stopTechnical=watchTechnicalAlerts(planId,rows=>{if(communicationState.selected!==planId)return;communicationState.technicalAlerts=rows;if(state.page==='Centro de Comunicaciones')main()},e=>{communicationState.feedback='Alertas técnicas: '+e.message;if(state.page==='Centro de Comunicaciones')main()});
 communicationState.stopStatus=watchCommunicationStatus(planId,row=>{if(communicationState.selected!==planId)return;communicationState.status=row;if(state.page==='Centro de Comunicaciones')main()},e=>{communicationState.feedback='Seguimiento: '+e.message;if(state.page==='Centro de Comunicaciones')main()});
 try{communicationState.details=await readCommunicationEvidence(planId)}catch(e){communicationState.error=e.code==='permission-denied'?'No se pudo consultar la evidencia: compruebe las reglas de Firestore publicadas y los permisos del analista.':e.code==='failed-precondition'?'Firebase requiere crear el índice compuesto de consumos (uid + planId). Consulte el archivo firestore.indexes.json incluido.':e.message}finally{communicationState.loading=false;if(state.page==='Centro de Comunicaciones'&&communicationState.selected===planId)main()}}
function bindCommunicationModal(){
 document.querySelector('#comm78Open')?.addEventListener('click',()=>{communicationState.modalOpen=true;acknowledgeCommunication(communicationState.selected);main();document.querySelector('#comm78Reply')?.focus()});
 const close=()=>{communicationState.modalOpen=false;main()};
 document.querySelector('#comm78Close')?.addEventListener('click',close);
 document.querySelector('#comm78Overlay')?.addEventListener('click',e=>{if(e.target.id==='comm78Overlay')close()});
 const field=document.querySelector('#comm78Reply');
 if(field){field.addEventListener('input',e=>{communicationState.draft=e.target.value});field.addEventListener('keydown',e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();document.querySelector('#comm78Send')?.click()}})}
 document.querySelector('#comm78Attention')?.addEventListener('change',async e=>{const next=e.target.value;e.target.disabled=true;try{await updateCommunicationStatus(communicationState.selected,next);communicationState.feedback='Seguimiento confirmado en Firebase.'}catch(err){communicationState.feedback='No se guardó: '+err.message}finally{if(state.page==='Centro de Comunicaciones')main()}});
 document.querySelector('#comm78Send')?.addEventListener('click',async()=>{const body=communicationState.draft.trim();if(!body||communicationState.busy)return;const id=communicationState.selected;communicationState.busy=true;const btn=document.querySelector('#comm78Send');if(btn){btn.disabled=true;btn.textContent='Enviando…'}try{await sendCommunicationMessage(id,body,state.profile?.name||state.user.email);communicationState.draft='';communicationState.feedback='✓ Mensaje confirmado en Firebase.'}catch(err){communicationState.feedback='No se envió: '+err.message}finally{communicationState.busy=false;if(state.page==='Centro de Comunicaciones')main()}});
 document.querySelector('#technical90Report')?.addEventListener('click',async e=>{const input=document.querySelector('#technical90Description');const value=input?.value||'';e.currentTarget.disabled=true;try{await reportTechnicalAlert(communicationState.selected,value,state.profile?.name||state.user.email);communicationState.feedback='✓ Novedad técnica registrada en Firebase.'}catch(err){communicationState.feedback='No se registró: '+err.message;alert(communicationState.feedback)}finally{if(state.page==='Centro de Comunicaciones')main()}});
 document.querySelectorAll('[data-tech-save]').forEach(button=>button.addEventListener('click',async()=>{const id=button.dataset.techSave;const severity=document.querySelector(`[data-tech-severity="${id}"]`)?.value;const status=document.querySelector(`[data-tech-status="${id}"]`)?.value;const note=document.querySelector(`[data-tech-note="${id}"]`)?.value;button.disabled=true;try{await reviewTechnicalAlert(communicationState.selected,id,severity,status,note);communicationState.feedback='✓ Revisión técnica confirmada en Firebase.'}catch(err){communicationState.feedback='No se guardó: '+err.message;alert(communicationState.feedback)}finally{if(state.page==='Centro de Comunicaciones')main()}}));
 const thread=document.querySelector('#comm78Thread');if(thread)thread.scrollTop=thread.scrollHeight;
}
function bindCommunications(){bindCommunicationModal();document.querySelector('#comm81Archive')?.addEventListener('click',async()=>{if(!communicationState.selected)return;const id=communicationState.selected;try{await setCommunicationArchive(id,!isArchivedPlan(id));communicationState.feedback='Estado de archivo confirmado en Firebase.';main()}catch(e){alert('No se pudo archivar: '+e.message)}});document.querySelector('#comm80Close')?.addEventListener('click',()=>{communicationState.modalOpen=false;stopCommunicationWatch();state.page=communicationsReturnPage==='Centro de Comunicaciones'?'Inicio':communicationsReturnPage;main()});const search=document.querySelector('#commSearch');if(search)search.oninput=e=>{communicationState.search=e.target.value;const cards=document.querySelectorAll('[data-comm-plan].comm-card');cards.forEach(card=>{const txt=card.textContent.toLocaleLowerCase();card.hidden=!txt.includes(communicationState.search.toLocaleLowerCase())})};const reply=document.querySelector('#commReply');if(reply)reply.onkeydown=e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();document.querySelector('#commSend')?.click()}};const f=document.querySelector('#commFilter');if(f){f.value=communicationState.filter;f.onchange=()=>{communicationState.filter=f.value;main()}}document.querySelectorAll('[data-comm-plan]').forEach(b=>b.onclick=()=>loadCommunication(b.dataset.commPlan));document.querySelector('#commRefresh')?.addEventListener('click',()=>loadCommunication(communicationState.selected));
 document.querySelector('#commAttention')?.addEventListener('change',async e=>{const value=e.target.value;e.target.disabled=true;try{await updateCommunicationStatus(communicationState.selected,value);communicationState.feedback='Estado confirmado en Firebase.'}catch(err){communicationState.feedback='No se guardó: '+err.message}finally{communicationState.busy=false;if(state.page==='Centro de Comunicaciones')main()}});
 document.querySelector('#commReply')?.addEventListener('input',e=>{communicationState.draft=e.target.value});document.querySelector('#commSend')?.addEventListener('click',async()=>{const input=document.querySelector('#commReply');const body=input?.value?.trim();if(!body)return;const planId=communicationState.selected;const btn=document.querySelector('#commSend');if(communicationState.busy)return;communicationState.busy=true;btn.disabled=true;btn.textContent='Enviando…';try{await sendCommunicationMessage(planId,body,state.profile?.name||state.user.email);communicationState.feedback='Respuesta confirmada en Firebase.';communicationState.draft='';if(input)input.value=''}catch(err){communicationState.feedback='No se envió: '+err.message;communicationState.draft=body}finally{communicationState.busy=false;if(state.page==='Centro de Comunicaciones')main()}});
}

// V29.0.92: consulta deliberada y acotada; no se abren escuchas globales adicionales.
const techBoard91={rows:[],loaded:false,loading:false,error:'',analyst:'TODOS',severity:'TODAS',status:'TODOS',term:'',count:0};
async function loadTechnicalBoard91(){if(state.profile?.role!=='JEFE'||techBoard91.loading)return;techBoard91.loading=true;techBoard91.error='';main();const plans=state.plans.filter(p=>p.status!=='CANCELADO').sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))).slice(0,40);const results=[];let failures=0;for(let i=0;i<plans.length;i+=5){const batch=plans.slice(i,i+5);await Promise.all(batch.map(async p=>{try{const snap=await getDocs(query(collection(db,'activityTechnicalAlerts',p.id,'items'),orderBy('createdAt','desc'),limit(30)));for(const d of snap.docs)results.push({...d.data(),id:d.id,planId:p.id,activityName:p.activityName,analystName:p.analystName,date:p.date})}catch(e){failures++;techBoard91.error=e.message}}))}techBoard91.rows=results.sort((a,b)=>(b.createdAt?.seconds||0)-(a.createdAt?.seconds||0));techBoard91.count=plans.length;techBoard91.loaded=true;techBoard91.loading=false;if(failures)techBoard91.error=`No fue posible consultar ${failures} expediente(s): ${techBoard91.error}`;if(state.page==='Alertas Técnicas')main()}
function technicalBoard(){const rows=techBoard91.rows;const count=k=>rows.filter(a=>k==='ABIERTA'?a.status==='ABIERTA':k==='CRITICA'?a.severity==='CRITICA'&&a.status!=='RESUELTA':a.status===k).length;const analysts=[...new Set(rows.map(r=>r.analystName||'Sin asignar'))].sort();const filtered=rows.filter(a=>(techBoard91.analyst==='TODOS'||(a.analystName||'Sin asignar')===techBoard91.analyst)&&(techBoard91.severity==='TODAS'||a.severity===techBoard91.severity)&&(techBoard91.status==='TODOS'||a.status===techBoard91.status)&&`${a.description} ${a.activityName} ${a.analystName}`.toLocaleLowerCase().includes(techBoard91.term.toLocaleLowerCase()));const options=(values,sel)=>values.map(([v,t])=>`<option value="${esc(v)}" ${sel===v?'selected':''}>${esc(t)}</option>`).join('');return `${heading('CALIDAD Y SEGUIMIENTO','Centro de Alertas Técnicas','Vigilancia de desviaciones e incidencias del laboratorio: clasificación por criticidad, responsables y seguimiento documentado.',`<button class="primary" id="tech91Refresh">${techBoard91.loading?'Consultando…':'↻ Actualizar expedientes'}</button>`)}<div class="tech91-metrics"><div class="tech91-kpi"><small>INCIDENCIAS ABIERTAS</small><strong>${count('ABIERTA')}</strong><span>Sin resolución confirmada</span></div><div class="tech91-kpi danger"><small>CRÍTICAS ACTIVAS</small><strong>${count('CRITICA')}</strong><span>Atención prioritaria</span></div><div class="tech91-kpi amber"><small>EN SEGUIMIENTO</small><strong>${count('EN_SEGUIMIENTO')}</strong><span>Revisión en curso</span></div><div class="tech91-kpi green"><small>RESUELTAS</small><strong>${count('RESUELTA')}</strong><span>Con historial de revisión</span></div></div><section class="panel tech91-panel"><div class="panel-heading"><div><h3>Expedientes técnicos</h3><p class="muted">${techBoard91.loaded?`${rows.length} incidencias en ${techBoard91.count} actividades consultadas`:'Seleccione «Actualizar expedientes» para consultar los registros reales.'}</p></div><span class="record-count">Consulta bajo demanda</span></div>${techBoard91.error?`<p class="tech91-error">${esc(techBoard91.error)}</p>`:''}<div class="tech91-filters"><label>Analista<select id="tech91Analyst">${options([['TODOS','Todos los analistas'],...analysts.map(a=>[a,a])],techBoard91.analyst)}</select></label><label>Clasificación<select id="tech91Severity">${options([['TODAS','Todas'],['INFORMATIVA','Informativa'],['REVISION','Pendiente de revisión'],['CRITICA','Crítica']],techBoard91.severity)}</select></label><label>Estado<select id="tech91Status">${options([['TODOS','Todos'],['ABIERTA','Abierta'],['EN_SEGUIMIENTO','En seguimiento'],['RESUELTA','Resuelta']],techBoard91.status)}</select></label><label>Buscar<input id="tech91Term" value="${esc(techBoard91.term)}" placeholder="Actividad o descripción"></label></div><div class="tech91-list">${techBoard91.loading?'<p class="muted">Consultando las incidencias autorizadas en Firebase…</p>':filtered.length?filtered.map(a=>`<article class="tech91-row"><div class="tech91-symbol ${a.severity==='CRITICA'?'danger':a.severity==='REVISION'?'amber':'blue'}">${a.severity==='CRITICA'?'!':a.severity==='REVISION'?'◷':'i'}</div><div class="tech91-detail"><div class="tech91-tags"><span>${a.severity==='CRITICA'?'Crítica':a.severity==='REVISION'?'Pendiente de revisión':'Informativa'}</span><span>${a.status==='RESUELTA'?'Resuelta':a.status==='EN_SEGUIMIENTO'?'En seguimiento':'Abierta'}</span></div><h4>${esc(a.activityName||'Actividad')}</h4><p>${esc(a.description||'')}</p><small>${esc(a.analystName||'Analista')} · ${esc(a.date||'')} · ${esc(a.authorName||'')}</small></div><button class="outline" data-tech91-open="${esc(a.planId)}">Ver expediente →</button></article>`).join(''):'<div class="tech91-empty">No hay incidencias que coincidan con los filtros y expedientes consultados.</div>'}</div><p class="cfg91-note">Alcance de esta consulta: hasta 40 actividades recientes y 30 novedades por actividad. No representa necesariamente todo el histórico. Las revisiones se realizan en el expediente, conservando el historial original.</p></section>`}
