// V29.0.41: ejecución real; las cancelaciones nunca se muestran en Mi Jornada.
function journeyPage(){
 const boss=state.profile.role==='JEFE', selected=boss?(state.journeyAnalyst||''):state.user.uid;
 const date=state.journeyDate||new Date().toLocaleDateString('en-CA');
 const active=state.plans.filter(p=>p.date===date&&p.status!=='CANCELADO'&&(!selected||p.analystId===selected)).sort((a,b)=>a.startMin-b.startMin);
 const minutes=active.reduce((n,p)=>n+(Number(p.durationMin)||0),0);
 const completed=active.filter(p=>p.status==='REALIZADO').length;
 const notifications=state.notifications.slice(0,5);
 const choices=boss?`<label>Analista<select id="journeyAnalyst"><option value="">Todos</option>${state.analysts.filter(operationalAnalyst).map(a=>`<option value="${esc(a.id)}" ${selected===a.id?'selected':''}>${esc(a.name||a.email)}</option>`).join('')}</select></label>`:'';
 return `${heading('EJECUCIÓN OPERATIVA','Mi Jornada Inteligente','Registro de ejecución del analista: muestras procesadas, consumos de reactivos, observaciones y cierre con evidencia.')}
 <section class="panel journey-overview journey-overview-v104"><div class="journey-compact-head"><div class="journey-compact-title"><span class="eyebrow">AGENDA OPERATIVA</span><h3>${boss?'Seguimiento del equipo':'Mi jornada asignada'}</h3></div><div class="journey-filters"><label><span class="sr-only">Fecha</span><input aria-label="Fecha de jornada" id="journeyDate" type="date" value="${esc(date)}"></label>${choices}<button type="button" class="outline" id="journeyToday">Hoy</button></div><span class="live-badge" id="journeyConnectionBadge">● ${connectionDiagnosis().title}</span></div><div class="journey-kpis journey-kpis-v104"><div class="j-kpi blue"><small>◫ Actividades vigentes</small><strong>${active.length}</strong><span>${active.length?'Asignadas para la fecha':'Sin asignaciones'}</span></div><div class="j-kpi teal"><small>◷ Carga programada</small><strong>${(minutes/60).toLocaleString('es-EC',{maximumFractionDigits:1})} h</strong><span>Tiempo planificado</span></div><div class="j-kpi green"><small>✓ Finalizadas</small><strong>${completed} / ${active.length}</strong><span>${active.length?Math.round(completed/active.length*100):0}% completado</span></div><div class="j-kpi ${active.some(p=>p.status==='EN_PROCESO')?'amber':'neutral'}"><small>● En proceso</small><strong>${active.filter(p=>p.status==='EN_PROCESO').length}</strong><span>${active.some(p=>p.status==='EN_PROCESO')?'Actividad en ejecución':'Sin actividad en ejecución'}</span></div></div><div class="journey-status-strip" role="status" id="journeyConnectionStrip"><span class="journey-light ${connectionDiagnosis().level}"></span><strong class="journey-connection-title">${connectionDiagnosis().title}</strong><span class="journey-connection-detail">${connectionDiagnosis().detail}</span><span class="journey-workflow-chip">${state.journeyError?'⚠ Error de jornada':active.some(p=>p.status==='EN_PROCESO')?'◷ Ejecución en curso':completed===active.length&&active.length?'✓ Jornada finalizada':'◉ Jornada en seguimiento'}</span><details class="journey-info"><summary>ⓘ Cómo funciona</summary><p>La ejecución se confirma mediante transacciones. Los registros de muestras y parámetros se guardan como borrador confirmado; los consumos se confirman en Firebase por transacción. La prevalidación comprueba datos técnicos, reactivos y cartas compartidas. El cierre definitivo permanece bloqueado hasta completar las validaciones de seguridad.</p></details></div></section>
 ${journeyControlsPanel(date,active)}
 <section class="panel journey-activities"><div class="panel-heading"><div><span class="eyebrow">AGENDA DIARIA</span><h3>Actividades del ${esc(date)}</h3></div><span class="table-tag">${active.length} vigente(s)</span></div>${active.length?`<div class="journey-list">${active.map((p,i)=>`<article class="journey-card journey-v41"><div class="journey-number">${i+1}</div><div class="journey-card-main"><div class="journey-card-top"><strong>${esc(p.activityName||'Actividad')}</strong><span class="journey-state ${p.status==='REALIZADO'?'completed':p.status==='EN_PROCESO'?'running':'programmed'}">${esc(p.status==='EN_PROCESO'?'EN PROCESO':p.status||'PROGRAMADO')}</span></div><div class="journey-card-meta"><span>◷ ${ptime(p.startMin)}–${ptime(p.endMin)}</span><span>${esc(p.area||'Sección')}</span>${boss?`<span>${esc(p.analystName||'Analista')}</span>`:''}<span>${(Number(p.durationMin||0)/60).toLocaleString('es-EC',{maximumFractionDigits:1})} h efectivas</span></div>${p.notes?`<p class="journey-instructions"><strong>Instrucción del JEFE:</strong> ${esc(p.notes)}</p>`:''}<details class="journey-details"><summary>Desglose y trazabilidad</summary><p>ID: ${esc(p.id)} · Ficha: ${esc(p.activityId||'—')} · Muestras previstas: ${esc(p.sampleCount??0)}</p><p>Revisión: ${esc(p.revision)} · Inicio confirmado: ${p.startedAt?.toDate?.()?.toLocaleString('es-EC')||'Pendiente'}</p></details><div class="journey-actions">${!boss&&p.status==='PROGRAMADO'?`<button class="primary" data-start-journey="${esc(p.id)}" ${journeyOpening.has(p.id)?'disabled':''}>${journeyOpening.has(p.id)?'Confirmando apertura…':'▶ Iniciar actividad'}</button>`:''}${p.status==='EN_PROCESO'?`<button class="primary" data-tech-journey="${esc(p.id)}">▤ Abrir expediente operativo completo</button><span class="journey-progress-note">● Cierre protegido por controles compartidos</span>`:''}${p.status==='REALIZADO'?'<span class="journey-progress-note">✓ Finalización confirmada</span>':''}</div></div></article>`).join('')}</div>`:'<div class="journey-empty"><strong>Sin actividades vigentes para esta fecha</strong><p>Las cancelaciones se conservan en el historial del planificador, pero no aparecen aquí.</p></div>'}</section>
 <section class="panel journey-events"><div class="panel-heading"><div><span class="eyebrow">CENTRO DE COMUNICACIONES · CANAL EXISTENTE</span><h3>Últimos avisos</h3></div><span class="table-tag">${state.notifications.length} visibles</span></div>${notifications.length?`<div class="journey-notices">${notifications.map(n=>`<div><strong>${esc(n.title||n.type||'Notificación')}</strong><p>${esc(n.message||n.body||'Aviso recibido')}</p></div>`).join('')}</div>`:'<p class="muted">No hay avisos recientes para esta cuenta.</p>'}</section><div id="modalRoot"></div>`;
}
function journeyControlsPanel(date,plans){
 const ids=new Set(plans.filter(p=>p.status!=='CANCELADO').map(p=>p.activityId));
 const cards=state.controlCards.filter(c=>c.status==='ACTIVO'&&Array.isArray(c.activityIds)&&c.activityIds.some(id=>ids.has(id)));
 if(!cards.length)return '';
 const record=c=>state.dailyControls.find(r=>r.controlId===c.id&&r.date===date);
 const completed=cards.filter(c=>record(c)?.status==='COMPLETADA').length;
 const failed=cards.filter(c=>record(c)&&record(c).status!=='COMPLETADA').length;
 const pending=cards.length-completed-failed;
 const headline=failed?`⛔ ${failed} control(es) no conforme(s) · Revisión de Calidad requerida`:pending?`⚠ ${pending} control(es) pendiente(s) · Complete antes del cierre`:'✓ Todos los controles conformes · Jornada habilitada para prevalidación';
 return `<section class="panel cc-journey-panel cc-compact-panel" aria-label="Controles obligatorios de la jornada"><div class="cc-compact-header"><div><span class="eyebrow">CONTROL DE CALIDAD · ${esc(date)}</span><h3>Cartas obligatorias <span class="cc-total">${completed}/${cards.length}</span></h3><p class="muted">Control diario compartido · Estado confirmado en Firebase</p></div><div class="cc-compact-metrics"><span class="cc-mini-count good">✓ ${completed} conformes</span><span class="cc-mini-count pending">◷ ${pending} pendientes</span>${failed?`<span class="cc-mini-count danger">! ${failed} no conformes</span>`:''}</div></div><div class="cc-progress" role="progressbar" aria-valuenow="${completed}" aria-valuemin="0" aria-valuemax="${cards.length}" aria-label="Controles conformes"><span style="width:${Math.round(100*completed/cards.length)}%"></span></div><div class="cc-operational-alert ${failed?'danger':pending?'pending':'good'}" role="status">${headline}</div><details class="cc-compact-details" ${pending||failed?'open':''}><summary>Ver ${cards.length} cartas vinculadas <span>▾</span></summary><div class="cc-compact-grid">${cards.map(c=>{const r=record(c),ok=r?.status==='COMPLETADA',bad=!!r&&!ok;return `<article class="cc-compact-item ${ok?'is-done':bad?'is-warning':'is-pending'}"><div class="cc-compact-item-head"><span class="cc-compact-icon">${ok?'✓':bad?'!':'◷'}</span><span class="cc-compact-status">${ok?'CONFORME':bad?'NO CONFORME':'PENDIENTE'}</span></div><strong title="${esc(c.name)}">${esc(c.name)}</strong><small>${esc(c.equipment||c.code||'Control diario')}</small>${r?`<span class="cc-compact-by" title="${esc(r.completedByName||'Responsable registrado')}">${esc(r.completedByName||'Registro compartido')}</span>`:c.kind==='MULTIPUNTO'?`<button class="primary cc-journey-open" type="button" data-card-id="${esc(c.id)}">Registrar ahora →</button>`:`<button class="outline cc-go-controls" type="button">Registrar →</button>`}</article>`}).join('')}</div></details></section>`;
}

