 tf.addEventListener('input',updateDirty);nf.addEventListener('input',updateDirty);
 const removeBinding=()=>{root.querySelectorAll('#workspaceParameters .journey-param-row button').forEach(b=>{if(b.dataset.autosaveBound)return;b.dataset.autosaveBound='1';b.addEventListener('click',()=>queueMicrotask(updateDirty));});};
 root.querySelector('#workspaceAddParameter').onclick=()=>{root.querySelector('#workspaceParameters').insertAdjacentHTML('beforeend',journeyParameterRow({}));bindParameterRemove(root);removeBinding();updateDirty();};bindParameterRemove(root);removeBinding();
