 const form=root.querySelector('#journeyConsumeForm'),btn=root.querySelector('#confirmJourneyConsume'),error=root.querySelector('#journeyConsumeError');
 const close=()=>root.innerHTML='';root.querySelector('#closeJourneyConsume').onclick=close;root.querySelector('#cancelJourneyConsume').onclick=close;
 let pending=null,busy=false;
