const management={from:new Date().toLocaleDateString('en-CA').slice(0,8)+'01',to:new Date().toLocaleDateString('en-CA'),analyst:'',status:'',insights:false};
const mgMinutes=p=>{const a=p.startedAt?.toDate?.(),b=p.finishedAt?.toDate?.();return a&&b&&b>=a?Math.round((b-a)/60000):null};
