const mgFmt=n=>`${Math.floor(Math.abs(n)/60)} h ${String(Math.round(Math.abs(n)%60)).padStart(2,'0')} min`;
function managementRows(){return state.plans.filter(p=>p.status!=='CANCELADO'&&p.date>=management.from&&p.date<=management.to&&(!management.analyst||p.analystId===management.analyst)&&(!management.status||p.status===management.status)).sort((a,b)=>String(b.date).localeCompare(String(a.date))||(a.startMin||0)-(b.startMin||0))}
