 const rows=managementRows(),done=rows.filter(p=>p.status==='REALIZADO'),withTimes=done.filter(p=>mgMinutes(p)!==null),plan=rows.reduce((n,p)=>n+mgPlan(p),0),real=withTimes.reduce((n,p)=>n+mgMinutes(p),0),plannedComparable=withTimes.reduce((n,p)=>n+mgPlan(p),0),running=rows.filter(p=>p.status==='EN_PROCESO').length;
 const ratio=rows.length?Math.round(done.length/rows.length*100):0;
