function timeFields(minutes, prefix){const n=Math.max(0,Number(minutes)||0);return `<div class="time-pair"><label>Horas<input name="${prefix}Hours" type="number" min="0" max="24" step="1" value="${Math.floor(n/60)}" required></label><label>Minutos<select name="${prefix}Minutes">${[0,15,30,45].map(v=>`<option value="${v}" ${n%60===v?'selected':''}>${String(v).padStart(2,'0')} min</option>`).join('')}${n%60%15!==0?`<option value="${n%60}" selected>${n%60} min (existente)</option>`:''}</select></label></div>`}
function formatDuration(minutes){const n=Number(minutes)||0;return `${Math.floor(n/60)} h ${String(n%60).padStart(2,'0')} min`}
